def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]

    # Count defections
    opp_def = sum(1 for a in op if a == 'D')
    my_def = sum(1 for a in my if a == 'D')

    # If opponent has never defected, cooperate (with rare late probe)
    if opp_def == 0:
        if n >= 95 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # If opponent always defects, defect
    if opp_def == n:
        return 'D'

    # Compute recent window statistics
    w = min(12, n)
    recent_op = op[-w:]
    recent_def = sum(1 for a in recent_op if a == 'D')
    recent_coop = w - recent_def

    # Long cooperative streak recently: preserve mutual cooperation
    if recent_def == 0:
        # Very confident cooperator; rare probe late
        if n >= 90 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Mostly cooperative recently: cooperate, forgive isolated defections
    if recent_def == 1:
        last_op = op[-1]
        if last_op == 'C':
            return 'C'
        # Opponent just defected after long cooperation: forgive once
        return 'C'

    # Detect repeated alternation (TFT-like lock) and break it
    if n >= 4:
        last4 = op[-4:]
        if last4 in (['C', 'D', 'C', 'D'], ['D', 'C', 'D', 'C']):
            # Break the alternation by cooperating twice
            if my[-1] == 'D':
                return 'C'
            return 'C'

    # Opponent has been defecting heavily recently
    if recent_def >= 8:
        return 'D'

    # Moderate defection rate: retaliate but with forgiveness
    last_op = op[-1]
    if last_op == 'D':
        # Retaliate, but occasionally forgive to allow recovery
        recent_def_streak = 0
        for i in range(n - 1, -1, -1):
            if op[i] == 'D':
                recent_def_streak += 1
            else:
                break
        if recent_def_streak >= 3:
            # Long defection streak: defect, but try occasional C to test recovery
            if recent_def_streak % 4 == 0:
                return 'C'
            return 'D'
        # Short defection: retaliate with probability, else forgive
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # Opponent cooperated last round; check overall defection pressure
    if recent_def >= 5:
        # Defecting quite often; be cautious
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    # Default: cooperate to sustain mutual cooperation
    return 'C'
